#!/usr/bin/env bash
# T3.1 English replay: 4 arms on LIAR + FakeNewsNet (deepseek candidates already
# generated by run_english_gen.sh). Warm-start, resumable. GPU.
set -u
export PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True
cd "$(dirname "$0")/.."

SCENARIOS="${SCENARIOS:-liar-full liar-10pct liar-5pct fakenewsnet-full fakenewsnet-10pct fakenewsnet-5pct}"
SEEDS="${SEEDS:-42 43 44 45 46}"
ARMS="all random-k score-k easy-k"

find_cand() {
  local sc=$1 seed=$2
  python3 -c "
import json, glob
hits = [p for p in glob.glob('outputs/revision-candidates/${sc}-s${seed}-*/candidates.json')
        if json.load(open(p)).get('complete') and json.load(open(p)).get('zero_shot')
        and json.load(open(p)).get('model') == 'deepseek-chat']
print(hits[-1] if hits else '')
"
}

for sc in $SCENARIOS; do
  grp="revision-controlled-${sc}-en"
  for seed in $SEEDS; do
    cand=$(find_cand "$sc" "$seed")
    [ -z "$cand" ] && { echo "MISSING candidates $sc s$seed"; continue; }
    for arm in $ARMS; do
      if compgen -G "outputs/${grp}/${arm}-s${seed}-*/results.json" >/dev/null; then
        echo "SKIP $sc s$seed $arm"; continue
      fi
      uv run python scripts/controlled_curatorship.py --replay \
        --candidates "$cand" --arm "$arm" --top-k 16 \
        --run-group "$grp" --learner-model neuralmind/bert-base-portuguese-cased
    done
  done
done
echo "=== ENGLISH REPLAY DONE ==="
